recipes.code:
{
  "inputs": [
    {
      "id": "statelode-token",
      "type": "promptString",
      "description": "StateLode workspace bearer token. Mint at app.statelode.dev.",
      "password": true
    }
  ],
  "servers": {
    "statelode": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "statelode-bridge@0.1.1"
      ],
      "env": {
        "STATELODE_TOKEN": "${input:statelode-token}"
      }
    }
  }
}
